{"implementation": "def solve(case):
    """Reduce a miniature parse tree by grammar-valid node deletion."""
    if not isinstance(case, dict):
        raise ValueError("case must be an object")
    if "nodes" not in case or "required_symbols" not in case:
        raise ValueError("case missing required fields")

    nodes = case["nodes"]
    required_symbols = case["required_symbols"]
    if not isinstance(nodes, list) or not nodes:
        raise ValueError("nodes must be a non-empty list")
    if not isinstance(required_symbols, list) or not all(isinstance(s, str) for s in required_symbols):
        raise ValueError("required_symbols must be a list of strings")

    required = set(required_symbols)
    by_id = {}
    source_index = {}
    roots = []

    for index, node in enumerate(nodes):
        if not isinstance(node, dict):
            raise ValueError("each node must be an object")
        for field in ("id", "parent", "symbol", "depth", "removable", "utility"):
            if field not in node:
                raise ValueError("node missing required field")

        node_id = node["id"]
        parent = node["parent"]
        symbol = node["symbol"]
        depth = node["depth"]
        removable = node["removable"]
        utility = node["utility"]

        if not isinstance(node_id, str):
            raise ValueError("node id must be a string")
        if node_id in by_id:
            raise ValueError("duplicate node id")
        if parent is not None and not isinstance(parent, str):
            raise ValueError("node parent must be a string or null")
        if not isinstance(symbol, str):
            raise ValueError("node symbol must be a string")
        if not isinstance(depth, int) or isinstance(depth, bool) or depth < 0:
            raise ValueError("node depth must be a non-negative integer")
        if not isinstance(removable, bool):
            raise ValueError("node removable must be a boolean")
        if not isinstance(utility, (int, float)) or isinstance(utility, bool):
            raise ValueError("node utility must be numeric")

        by_id[node_id] = node
        source_index[node_id] = index
        if parent is None:
            roots.append(node_id)

    if len(roots) != 1:
        raise ValueError("tree must contain exactly one root")

    children = {node_id: [] for node_id in by_id}
    for node in nodes:
        node_id = node["id"]
        parent = node["parent"]
        depth = node["depth"]
        if parent is None:
            if depth != 0:
                raise ValueError("root depth must be zero")
            continue
        if parent not in by_id:
            raise ValueError("node parent does not exist")
        if by_id[parent]["depth"] + 1 != depth:
            raise ValueError("node depth is inconsistent with parent")
        children[parent].append(node_id)

    seen_symbols = set()
    for node in nodes:
        seen_symbols.add(node["symbol"])
    if not required.issubset(seen_symbols):
        raise ValueError("required symbol is not represented")

    root_id = roots[0]
    retained = set(by_id)
    removed = []
    symbol_counts = {}
    for node in nodes:
        symbol = node["symbol"]
        symbol_counts[symbol] = symbol_counts.get(symbol, 0) + 1

    ordered = sorted(nodes, key=lambda node: (-node["depth"], node["id"]))

    for node in ordered:
        node_id = node["id"]
        symbol = node["symbol"]

        if node_id == root_id:
            continue
        if not node["removable"]:
            continue
        if symbol in required:
            continue
        if any(child_id in retained for child_id in children[node_id]):
            continue

        next_count = symbol_counts.get(symbol, 0) - 1
        valid = True
        for required_symbol in required:
            if required_symbol == symbol:
                if next_count <= 0:
                    valid = False
                    break
            elif symbol_counts.get(required_symbol, 0) <= 0:
                valid = False
                break
        if not valid:
            continue

        retained.remove(node_id)
        symbol_counts[symbol] = next_count
        removed.append(node_id)

    return {
        "removed_node_ids": removed,
        "retained_node_ids": sorted(retained),
    }
"}
